  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "vitest run",
    "build": "echo \"no build step configured\""
  },
  "devDependencies": {
    "vitest": "^3.1.3"
  }
}

import { randomUUID } from "node:crypto";
import { mkdir, readFile, rename, writeFile } from "node:fs/promises";
import path from "node:path";

const STATUSES = new Set(["reading", "finished"]);

export function createEmptyStore() {
  return { books: [] };
}

export function normalizeBook(input, existing) {
  const title = cleanText(input?.title);
  const author = cleanText(input?.author);
  const notes = cleanText(input?.notes);
  const status = input?.status === "finished" ? "finished" : "reading";

  if (!title) {
    const error = new Error("Title is required.");
    error.statusCode = 400;
    throw error;
  }
  if (!author) {
    const error = new Error("Author is required.");
    error.statusCode = 400;
    throw error;
  }
  if (input?.status != null && !STATUSES.has(input.status)) {
    const error = new Error("Status must be reading or finished.");
    error.statusCode = 400;
    throw error;
  }

  const now = new Date().toISOString();
  return {
    id: existing?.id ?? randomUUID(),
    title,
    author,
    notes,
    status,
    createdAt: existing?.createdAt ?? now,
    updatedAt: now,
    finishedAt: status === "finished" ? existing?.finishedAt ?? now : null,
  };
}

export function addBook(store, input) {
  const book = normalizeBook(input);
  return {
    store: { books: [book, ...store.books] },
    book,
  };
}

export function finishBook(store, id) {
  const index = store.books.findIndex((book) => book.id === id);
  if (index === -1) {
    const error = new Error("Book not found.");
    error.statusCode = 404;
    throw error;
  }
  const current = store.books[index];
  if (current.status === "finished") {
    return { store, book: current };
  }
  const book = normalizeBook(
    { ...current, status: "finished" },
    current,
  );
  const books = store.books.slice();
  books[index] = book;
  return { store: { books }, book };
}

export function getBook(store, id) {
  return store.books.find((book) => book.id === id) ?? null;
}

export function listBooks(store) {
  const reading = store.books.filter((book) => book.status === "reading");
  const finished = store.books.filter((book) => book.status === "finished");
  return { reading, finished };
}

export async function loadStore(filePath) {
  try {
    const raw = await readFile(filePath, "utf8");
    const parsed = JSON.parse(raw);
    if (!parsed || !Array.isArray(parsed.books)) return createEmptyStore();
    return { books: parsed.books.filter(isStoredBook) };
  } catch (error) {
    if (error && error.code === "ENOENT") return createEmptyStore();
    throw error;
  }
}

export async function saveStore(filePath, store) {
  await mkdir(path.dirname(filePath), { recursive: true });
  const temporary = `${filePath}.${process.pid}.tmp`;
  await writeFile(temporary, `${JSON.stringify(store, null, 2)}\n`, "utf8");
  await rename(temporary, filePath);
}

function cleanText(value) {
  return typeof value === "string" ? value.trim() : "";
}

function isStoredBook(value) {
  return (
    value &&
    typeof value.id === "string" &&
    typeof value.title === "string" &&
    typeof value.author === "string" &&
    (value.status === "reading" || value.status === "finished")
  );
}

function escapeHtml(value) {
  return String(value ?? "")
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;")
    .replaceAll("'", "&#39;");
}

function page(title, body) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)}</title>
  <style>
    :root { color-scheme: light; }
    body { margin: 0; font: 16px/1.45 system-ui, sans-serif; background: #f6f3ee; color: #1d1a16; }
    main { max-width: 42rem; margin: 0 auto; padding: 2rem 1.25rem 3rem; }
    h1, h2 { font-weight: 650; letter-spacing: -0.02em; }
    h1 { margin: 0 0 0.25rem; font-size: 1.8rem; }
    h2 { margin: 2rem 0 0.75rem; font-size: 1.1rem; }
    p { margin: 0.35rem 0; }
    a { color: #6b3f1d; }
    .lede { color: #5c534b; margin-bottom: 1.5rem; }
    .card, form { background: #fffdf9; border: 1px solid #e4dcd1; border-radius: 12px; padding: 0.9rem 1rem; }
    .list { display: grid; gap: 0.6rem; }
    .card { display: flex; justify-content: space-between; gap: 1rem; align-items: center; }
    .muted { color: #6d645c; }
    form { display: grid; gap: 0.75rem; }
    label { display: grid; gap: 0.3rem; font-size: 0.92rem; }
    input, textarea { font: inherit; padding: 0.55rem 0.65rem; border: 1px solid #d8cfc4; border-radius: 8px; background: #fff; }
    textarea { min-height: 7rem; resize: vertical; }
    button, .button { font: inherit; border: 0; border-radius: 999px; padding: 0.45rem 0.85rem; background: #2f241c; color: #fff; cursor: pointer; text-decoration: none; display: inline-block; }
    button.quiet { background: transparent; color: #6b3f1d; border: 1px solid #d8cfc4; }
    .row { display: flex; gap: 0.5rem; flex-wrap: wrap; align-items: center; }
    .notes { white-space: pre-wrap; }
    .error { color: #8a2a1b; }
  </style>
</head>
<body>
  <main>
    ${body}
  </main>
</body>
</html>`;
}

export function renderHome(store, error) {
  const reading = store.books.filter((book) => book.status === "reading");
  const finished = store.books.filter((book) => book.status === "finished");
  return page(
    "Books",
    `
    <h1>Books</h1>
    <p class="lede">What you're reading, and what you've finished.</p>
    ${error ? `<p class="error">${escapeHtml(error)}</p>` : ""}
    <form method="post" action="/books">
      <label>Title <input name="title" required maxlength="200"></label>
      <label>Author <input name="author" required maxlength="200"></label>
      <label>Notes <textarea name="notes" maxlength="4000"></textarea></label>
      <div class="row"><button type="submit">Add book</button></div>
    </form>
    <h2>Currently reading</h2>
    ${bookList(reading, true)}
    <h2>Finished</h2>
    ${bookList(finished, false)}
    `,
  );
}

export function renderBook(book) {
  return page(
    book.title,
    `
    <p><a href="/">All books</a></p>
    <h1>${escapeHtml(book.title)}</h1>
    <p>${escapeHtml(book.author)}</p>
    <p class="muted">${book.status === "finished" ? "Finished" : "Currently reading"}</p>
    <h2>Notes</h2>
    <p class="notes">${book.notes ? escapeHtml(book.notes) : "No notes yet."}</p>
    <div class="row">
      ${
        book.status === "reading"
          ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button type="submit">Mark finished</button></form>`
          : ""
      }
      <a class="button" href="/books/${encodeURIComponent(book.id)}">Shareable link</a>
    </div>
    `,
  );
}

export function renderNotFound() {
  return page(
    "Not found",
    `<h1>Not found</h1><p><a href="/">Back to books</a></p>`,
  );
}

function bookList(books, canFinish) {
  if (books.length === 0) return `<p class="muted">None yet.</p>`;
  return `<div class="list">${books
    .map(
      (book) => `<article class="card">
        <div>
          <div><a href="/books/${encodeURIComponent(book.id)}">${escapeHtml(book.title)}</a></div>
          <div class="muted">${escapeHtml(book.author)}</div>
        </div>
        ${
          canFinish
            ? `<form method="post" action="/books/${encodeURIComponent(book.id)}/finish"><button class="quiet" type="submit">Finish</button></form>`
            : ""
        }
      </article>`,
    )
    .join("")}</div>`;
}

import { createServer } from "node:http";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { renderBook, renderHome, renderNotFound } from "./lib/html.js";
import {
  addBook,
  finishBook,
  getBook,
  loadStore,
  saveStore,
} from "./lib/store.js";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const dataFile = process.env.BOOKS_FILE
  ? path.resolve(process.env.BOOKS_FILE)
  : path.join(__dirname, "data", "books.json");
const port = Number(process.env.PORT || 3000);

let writeQueue = Promise.resolve();

function withStore(mutator) {
  const run = writeQueue.then(async () => {
    const store = await loadStore(dataFile);
    const result = await mutator(store);
    if (result.store) await saveStore(dataFile, result.store);
    return result;
  });
  writeQueue = run.then(
    () => undefined,
    () => undefined,
  );
  return run;
}

function readBody(req) {
  return new Promise((resolve, reject) => {
    const chunks = [];
    let size = 0;
    req.on("data", (chunk) => {
      size += chunk.length;
      if (size > 100_000) {
        reject(Object.assign(new Error("Body too large."), { statusCode: 413 }));
        req.destroy();
        return;
      }
      chunks.push(chunk);
    });
    req.on("end", () => {
      const raw = Buffer.concat(chunks).toString("utf8");
      const params = new URLSearchParams(raw);
      resolve({
        title: params.get("title") ?? "",
        author: params.get("author") ?? "",
        notes: params.get("notes") ?? "",
        status: params.get("status") || undefined,
      });
    });
    req.on("error", reject);
  });
}

function send(res, status, html) {
  res.writeHead(status, {
    "content-type": "text/html; charset=utf-8",
    "cache-control": "no-store",
  });
  res.end(html);
}

function redirect(res, location) {
  res.writeHead(303, { location });
  res.end();
}

export function createApp() {
  return createServer(async (req, res) => {
    try {
      const url = new URL(req.url || "/", "http://localhost");
      const pathname = url.pathname;
      const method = req.method || "GET";

      if (method === "GET" && pathname === "/") {
        const store = await loadStore(dataFile);
        send(res, 200, renderHome(store));
        return;
      }

      const bookMatch = pathname.match(/^\/books\/([^/]+)$/);
      if (method === "GET" && bookMatch) {
        const store = await loadStore(dataFile);
        const book = getBook(store, decodeURIComponent(bookMatch[1]));
        if (!book) {
          send(res, 404, renderNotFound());
          return;
        }
        send(res, 200, renderBook(book));
        return;
      }

      if (method === "POST" && pathname === "/books") {
        const input = await readBody(req);
        try {
          const { book } = await withStore((store) => addBook(store, input));
          redirect(res, `/books/${encodeURIComponent(book.id)}`);
        } catch (error) {
          if (error.statusCode === 400) {
            const store = await loadStore(dataFile);
            send(res, 400, renderHome(store, error.message));
            return;
          }
          throw error;
        }
        return;
      }

      const finishMatch = pathname.match(/^\/books\/([^/]+)\/finish$/);
      if (method === "POST" && finishMatch) {
        const id = decodeURIComponent(finishMatch[1]);
        try {
          await withStore((store) => finishBook(store, id));
          redirect(res, `/books/${encodeURIComponent(id)}`);
        } catch (error) {
          if (error.statusCode === 404) {
            send(res, 404, renderNotFound());
            return;
          }
          throw error;
        }
        return;
      }

      send(res, 404, renderNotFound());
    } catch (error) {
      const status = error.statusCode || 500;
      send(res, status, renderNotFound());
    }
  });
}

const isMain = process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1]);

if (isMain) {
  const server = createApp();
  server.listen(port, () => {
    process.stdout.write(`Books app listening on http://localhost:${port}\n`);
  });
}

